use vstd::prelude::*;

verus! {
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
        requires
            // The input array can be of any length, including zero.
            true,
        ensures
            // The length of the result is twice the length of the input array.
            result.len() == 2 * arr.len(),
        ensures
            // For every index k in the input array, the output at position 2k is elem,
            // and at position 2k + 1 is the k-th element of the input array.
            forall |k: nat| 0 <= k < arr.len() ==> 
                result[2 * k] == elem && result[2 * k + 1] == arr[k as usize]
    {
        let mut result: Vec<i32> = Vec::new();
        let len = arr.len();
        let mut idx: usize = 0;

        while idx < len
            invariant
                idx <= len,
                result.len() == 2 * idx,
                forall |k: nat| 0 <= k < idx ==> 
                    result[2 * k] == elem && result[2 * k + 1] == arr[k as usize],
            decreases len - idx,
        {
            result.push(elem);
            result.push(arr[idx]);
            idx = idx + 1;
        }

        result
    }
}

